import React, { useState, useEffect, useRef } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { Link } from 'react-router-dom'
import PostCard from '../components/PostCard'

export default function Feed() {
    const { user, profile } = useAuth()
    const [posts, setPosts] = useState([])
    const [loading, setLoading] = useState(true)
    const [newPost, setNewPost] = useState('')
    const [posting, setPosting] = useState(false)
    const [selectedImage, setSelectedImage] = useState(null)
    const [imagePreview, setImagePreview] = useState(null)
    const [filter, setFilter] = useState('all') // all, following
    const fileInputRef = useRef(null)

    useEffect(() => {
        loadPosts()
    }, [filter])

    const loadPosts = async () => {
        setLoading(true)
        try {
            let query = supabase
                .from('posts')
                .select(`
                    *,
                    profiles:user_id (id, username, full_name, avatar_url),
                    comments:post_comments (
                        *,
                        profiles:user_id (id, username, full_name, avatar_url),
                        replies:comment_replies (
                            *,
                            profiles:user_id (id, username, full_name, avatar_url)
                        )
                    ),
                    reactions:post_reactions (type, user_id)
                `)
                .order('created_at', { ascending: false })
                .limit(50)

            // If filter is 'following', only show posts from followed users
            if (filter === 'following' && user) {
                const { data: following } = await supabase
                    .from('followers')
                    .select('following_id')
                    .eq('follower_id', user.id)

                const followingIds = following?.map(f => f.following_id) || []
                if (followingIds.length > 0) {
                    query = query.in('user_id', followingIds)
                } else {
                    setPosts([])
                    setLoading(false)
                    return
                }
            }

            const { data, error } = await query

            if (error) throw error
            setPosts(data || [])
        } catch (error) {
            console.error('Error loading posts:', error)
        } finally {
            setLoading(false)
        }
    }

    const handleImageUpload = (e) => {
        const file = e.target.files[0]
        if (file) {
            setSelectedImage(file)
            const reader = new FileReader()
            reader.onload = () => {
                setImagePreview(reader.result)
            }
            reader.readAsDataURL(file)
        }
    }

    const removeImage = () => {
        setSelectedImage(null)
        setImagePreview(null)
        if (fileInputRef.current) {
            fileInputRef.current.value = ''
        }
    }

    const handleCreatePost = async (e) => {
        e.preventDefault()
        if (!newPost.trim() && !selectedImage) {
            alert('Please write something or add an image')
            return
        }

        setPosting(true)
        try {
            let imageUrl = null
            if (selectedImage) {
                // Convert to base64 for simplicity (in production, upload to storage)
                const reader = new FileReader()
                const imageData = await new Promise((resolve) => {
                    reader.onload = () => resolve(reader.result)
                    reader.readAsDataURL(selectedImage)
                })
                imageUrl = imageData
            }

            const { data, error } = await supabase
                .from('posts')
                .insert({
                    user_id: user.id,
                    text: newPost.trim(),
                    image: imageUrl,
                    likes_count: 0,
                    comments_count: 0
                })
                .select()
                .single()

            if (error) throw error

            // Reload posts
            setNewPost('')
            removeImage()
            await loadPosts()
        } catch (error) {
            console.error('Error creating post:', error)
            alert('Failed to create post. Please try again.')
        } finally {
            setPosting(false)
        }
    }

    return (
        <div className="max-w-3xl mx-auto">
            {/* Header */}
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800">📰 Feed</h1>
                    <p className="text-gray-500">Stay updated with the latest predictions and discussions</p>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={() => setFilter('all')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'all'
                                ? 'bg-green-600 text-white'
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        All
                    </button>
                    <button
                        onClick={() => setFilter('following')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'following'
                                ? 'bg-green-600 text-white'
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        Following
                    </button>
                </div>
            </div>

            {/* Create Post */}
            <div className="bg-white rounded-xl shadow-md p-4 mb-6">
                <div className="flex items-center gap-3 mb-3">
                    <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                        {profile?.username?.[0]?.toUpperCase() || 'U'}
                    </div>
                    <span className="font-semibold text-gray-800">
                        {profile?.full_name || profile?.username || 'User'}
                    </span>
                </div>

                <form onSubmit={handleCreatePost}>
                    <textarea
                        value={newPost}
                        onChange={(e) => setNewPost(e.target.value)}
                        placeholder="What's on your mind? Share a prediction, analysis, or football news..."
                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500 resize-none"
                        rows="3"
                    />

                    {/* Image Preview */}
                    {imagePreview && (
                        <div className="relative mt-3">
                            <img 
                                src={imagePreview} 
                                alt="Preview" 
                                className="max-h-64 rounded-lg object-contain bg-gray-100"
                            />
                            <button
                                type="button"
                                onClick={removeImage}
                                className="absolute top-2 right-2 bg-red-500 text-white rounded-full w-8 h-8 flex items-center justify-center hover:bg-red-600"
                            >
                                ×
                            </button>
                        </div>
                    )}

                    <div className="flex items-center justify-between mt-3">
                        <div className="flex gap-2">
                            <button
                                type="button"
                                onClick={() => fileInputRef.current?.click()}
                                className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition text-sm"
                            >
                                📷 Add Image
                            </button>
                            <input
                                ref={fileInputRef}
                                type="file"
                                accept="image/*"
                                onChange={handleImageUpload}
                                className="hidden"
                            />
                        </div>
                        <button
                            type="submit"
                            disabled={posting || (!newPost.trim() && !selectedImage)}
                            className="px-6 py-2 bg-green-600 text-white rounded-lg font-semibold hover:bg-green-700 transition disabled:opacity-50"
                        >
                            {posting ? 'Posting...' : 'Post'}
                        </button>
                    </div>
                </form>
            </div>

            {/* Posts */}
            {loading ? (
                <div className="text-center py-12">
                    <div className="text-gray-500">Loading posts...</div>
                </div>
            ) : posts.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">📝</div>
                    <p className="text-gray-500">No posts yet</p>
                    <p className="text-sm text-gray-400">Be the first to share something!</p>
                </div>
            ) : (
                <div className="space-y-6">
                    {posts.map((post) => (
                        <PostCard 
                            key={post.id} 
                            post={post} 
                            onRefresh={loadPosts}
                            currentUser={user}
                        />
                    ))}
                </div>
            )}
        </div>
    )
}
